mapper.select:
SELECT `id`, `tenant_id`, `task_type`, `aggregate_id`, `idempotency_key`, `payload_json`, `state`, `attempts`, `max_attempts`, `available_at`, `locked_at`, `lease_token`, `last_error`, `created_at`, `updated_at` FROM `taskoutbox`
WHERE `tenant_id` = #{tenantId,jdbcType=INTEGER}
ORDER BY `id` LIMIT #{limit,jdbcType=INTEGER} OFFSET #{offset,jdbcType=INTEGER}
